<template>
 <main v-if="props.active" class="product-label-author">
  <el-card v-for="screen in screens" :key="screen.key" shadow="never">
   <template #header><div class="card-header"><div><strong>商品标签管理</strong><p class="sub">按分组维护文字和图片标签；启用与商城展示分别控制。</p></div><div class="actions"><el-button v-if="canManage" :disabled="!model.writable() || model.viewLocked() || !state.snapshot?.can_create_group" @click="screen.createGroup">添加分组</el-button><el-button v-if="canManage" type="primary" :disabled="!model.writable() || model.viewLocked() || !state.snapshot?.can_create" @click="screen.create">添加标签</el-button></div></div></template>
   <el-alert v-if="state.pending" title="原商品标签操作结果尚未确认，新的提交已暂停" type="warning" :closable="false" class="notice"><p>未找到回执仍表示结果未知。可以读取原回执，或核对并封存原请求。</p><div class="actions"><el-button :disabled="state.busy" @click="screen.receipt">读取原回执</el-button><el-button :disabled="state.busy" @click="screen.resolve">核对并封存原请求</el-button><el-button v-if="state.retryReady && canManage" :disabled="state.busy" @click="screen.retry">原样重试</el-button></div></el-alert>
   <el-alert v-if="!canView" title="当前账号没有商品标签查看权限" type="warning" :closable="false" />
   <el-alert v-if="state.error || state.pendingError" :title="state.error || state.pendingError" type="error" :closable="false" class="notice" />
   <el-alert v-if="state.notice" :title="state.notice" type="success" :closable="false" class="notice" />
   <template v-if="canView">
    <el-alert v-if="!canManage" title="当前账号仅可查看商品标签。" type="info" :closable="false" class="notice" />
    <el-alert v-if="state.snapshot && !state.snapshot.write_ready" title="此环境尚未安装商品标签安全写入能力，目录可查看" type="warning" :closable="false" />
    <el-alert v-if="state.snapshot && !state.snapshot.can_create" title="标签目录已达容量上限，暂不能新增；已有标签仍可维护" type="warning" :closable="false" />
    <el-alert v-if="state.snapshot && !state.snapshot.can_create_group" title="分组目录已达容量上限，暂不能新增分组" type="warning" :closable="false" />
    <p v-if="state.loading" role="status">正在读取商品标签…</p>
    <div v-if="state.snapshot && !state.loading" class="catalog-layout">
     <aside class="group-panel"><h3>标签分组</h3><div class="filters"><label>搜索分组<input aria-label="标签分组搜索" :value="state.filters.groupDraft" :disabled="model.viewLocked()" @input="screen.groupKeyword(($event.target as HTMLInputElement).value)" @keyup.enter="screen.searchGroups" /></label><el-button :disabled="model.viewLocked()" @click="screen.searchGroups">查询分组</el-button></div><el-button :disabled="model.viewLocked()" @click="screen.allGroups">全部标签</el-button>
      <div v-for="group in groups" :key="group.key" class="label-group-row" :class="{ selected:group.selected }"><button class="group-name" :title="group.row.name" :aria-label="group.row.name || '空名称历史分组'" :disabled="model.viewLocked()" @click="group.select"><span class="group-name-text">{{ group.row.name || '空名称历史分组' }}</span></button><div class="group-meta"><span class="group-sort">排序 {{ group.row.sort }}<small v-if="group.row.id===1">（默认）</small></span><div v-if="canManage" class="actions"><el-button link :disabled="!model.writable() || model.viewLocked()" @click="group.edit">编辑分组</el-button><el-button link type="danger" :disabled="!model.writable() || model.viewLocked() || group.row.id===1" @click="group.remove">删除分组</el-button></div></div></div>
      <nav class="pager actions"><span>共 {{ visibleGroups.length }} 组，第 {{ state.filters.groupPage }}/{{ groupPageCount }} 页</span><el-button :disabled="model.viewLocked() || state.filters.groupPage<=1" @click="screen.previousGroup">分组上一页</el-button><el-button :disabled="model.viewLocked() || state.filters.groupPage>=groupPageCount" @click="screen.nextGroup">分组下一页</el-button></nav>
     </aside>
     <section class="label-panel"><div class="filters"><label>搜索标签<input aria-label="商品标签搜索" placeholder="标签名称或ID" :value="state.filters.draft" :disabled="model.viewLocked()" @input="screen.keyword(($event.target as HTMLInputElement).value)" @keyup.enter="screen.search" /></label><el-button :disabled="model.viewLocked()" @click="screen.search">查询</el-button><el-button :disabled="model.viewLocked()" @click="screen.reset">重置</el-button><el-button :disabled="state.busy" @click="screen.refresh">刷新</el-button></div>
      <div v-if="canManage" class="actions"><span>已选择 {{ state.selected.length }} 项（最多50项）</span><el-button type="danger" :disabled="!model.writable() || model.viewLocked() || !state.selected.length" @click="screen.batch">删除选中标签</el-button></div>
      <div class="table-scroll"><table aria-label="平台商品标签列表"><thead><tr><th v-if="canManage">选择</th><th>标签</th><th>是否开启</th><th>移动端展示</th><th>排序</th><th>创建时间</th><th v-if="canManage">操作</th></tr></thead><tbody><tr v-for="item in rows" :key="item.key" class="product-label-row">
       <td v-if="canManage"><input type="checkbox" :aria-label="`选择标签${item.row.id}`" :checked="item.selected" :disabled="!model.writable() || model.viewLocked()" @change="item.toggle(($event.target as HTMLInputElement).checked)" /></td>
       <td class="product-label-cell" :title="item.row.label_name" :aria-label="item.row.label_name || '空名称历史标签'"><span v-if="item.row.style_type===2" class="word-preview"><img v-if="item.preview.icon" :src="item.preview.icon" alt="商品标签图标" @error="item.imageError" /><span v-else>图片暂无可用预览</span></span><span v-else class="word-preview label-list-preview" :style="wordStyle(item.preview)"><span class="label-list-name" :title="item.row.label_name" :aria-label="item.row.label_name || '空名称历史标签'">{{ item.row.label_name || '空名称历史标签' }}</span></span><p class="sub label-list-context" :title="groupName(item.row.label_cate)">#{{ item.row.id }} · {{ groupName(item.row.label_cate) }}<span v-if="![1,2].includes(item.row.style_type)"> · 历史样式 {{ item.row.style_type }}</span></p></td>
       <td class="status">{{ flagLabel(item.row.status) }}<el-button v-if="canManage" link :disabled="!model.writable() || model.viewLocked()" @click="item.status">{{ item.row.status===1?'关闭':'开启' }}</el-button></td>
       <td class="status">{{ flagLabel(item.row.is_show) }}<el-button v-if="canManage" link :disabled="!model.writable() || model.viewLocked()" @click="item.show">{{ item.row.is_show===1?'隐藏':'显示' }}</el-button></td><td>{{ item.row.sort }}</td><td class="date">{{ addedTime(item.row.add_time) }}</td><td v-if="canManage"><div class="actions"><el-button link type="primary" :disabled="!model.writable() || model.viewLocked()" @click="item.edit">编辑标签</el-button><el-button link type="danger" :disabled="!model.writable() || model.viewLocked() || item.row.id<=5 && item.row.label_cate===1" @click="item.remove">删除标签</el-button></div></td>
      </tr></tbody></table><p v-if="!visible.length" class="empty">暂无商品标签</p></div><nav class="pager actions" aria-label="商品标签分页"><span>共 {{ visible.length }} 项，第 {{ state.filters.page }}/{{ pageCount }} 页</span><el-button :disabled="model.viewLocked() || state.filters.page<=1" @click="screen.previous">上一页</el-button><el-button :disabled="model.viewLocked() || state.filters.page>=pageCount" @click="screen.next">下一页</el-button></nav>
     </section>
    </div>
   </template>
  </el-card>
  <el-dialog v-for="editor in editors" :key="editor.key" class="product-label-author-dialog" top="16px" :model-value="true" :title="state.editor?.row?'编辑商品标签':'添加商品标签'" width="min(620px, calc(100vw - 24px))" :show-close="false" :close-on-click-modal="false" :close-on-press-escape="false">
   <el-alert v-if="state.error" :title="state.error" type="error" :closable="false" />
   <label class="field">标签名称<input aria-label="编辑标签名称" :value="editor.draft.label_name" :disabled="!model.writable() || !!state.gallery" @input="editor.field('label_name', ($event.target as HTMLInputElement).value)" @keyup.enter="editor.submit" /></label><p class="sub">{{ editor.count }}/20 个字符；未修改的历史名称可原样保留。</p>
   <label class="field">标签分组<select aria-label="编辑标签分组" :value="String(editor.draft.label_cate)" :disabled="!model.writable() || !!state.gallery" @change="editor.field('label_cate', ($event.target as HTMLSelectElement).value)"><option v-if="!state.snapshot?.groups.some(g=>g.id===Number(editor.draft.label_cate))" :value="String(editor.draft.label_cate)">{{ Number(editor.draft.label_cate)===0?'请选择分组':'失效历史分组 #'+editor.draft.label_cate+'（原样可保留）' }}</option><option v-for="group in state.snapshot?.groups" :key="group.id" :value="String(group.id)">{{ group.name || '空名称分组 #'+group.id }}</option></select></label>
   <label class="field">效果设置<select aria-label="标签样式" :value="String(editor.draft.style_type)" :disabled="!model.writable() || !!state.gallery" @change="editor.field('style_type', ($event.target as HTMLSelectElement).value)"><option v-if="![1,2].includes(Number(editor.draft.style_type))" :value="String(editor.draft.style_type)">历史样式 {{ editor.draft.style_type }}（原样可保留）</option><option value="1">文字标签</option><option value="2">图片标签</option></select></label>
   <section v-if="Number(editor.draft.style_type)===1" class="style-controls"><div v-for="colour in colourFields" :key="colour.key" class="field"><label>{{ colour.label }}</label><div class="colour-line"><input :aria-label="colour.label" :value="editor.draft[colour.key]" :disabled="!model.writable() || !!state.gallery" @input="editor.colour(colour.key, ($event.target as HTMLInputElement).value)" /><el-color-picker :model-value="editor.preview[colour.key]" show-alpha :disabled="!model.writable() || !!state.gallery" @update:model-value="editor.colour(colour.key,$event)" /></div></div></section>
   <section v-if="Number(editor.draft.style_type)===2" class="field"><label>上传图标</label><div class="image-line"><img v-if="editor.preview.icon" :key="editor.imageKey" :src="editor.preview.icon" alt="标签图标预览" @error="editor.imageError" /><span v-else>无可用预览</span><el-button :disabled="!model.writable() || !!state.gallery" @click="editor.picker">选择图标</el-button><el-button :disabled="!model.writable() || !!state.gallery || !editor.draft.icon" @click="editor.clearIcon">移除图标</el-button></div><input aria-label="标签图标原始地址" :value="editor.draft.icon" :disabled="!model.writable() || !!state.gallery" @input="editor.icon(($event.target as HTMLInputElement).value)" /><p class="sub">建议80×30。图库预览与保存原值分开；切换样式不清除图片和颜色。</p></section>
   <label class="field">排序<input aria-label="编辑标签排序" inputmode="numeric" :value="String(editor.draft.sort)" :disabled="!model.writable() || !!state.gallery" @input="editor.field('sort',($event.target as HTMLInputElement).value)" @keyup.enter="editor.submit" /></label><p class="sub">新排序0至2147483647，未修改的历史负数可保留。</p>
   <label v-for="flag in flagFields" :key="flag.key" class="field">{{ flag.label }}<select :aria-label="flag.label" :value="String(editor.draft[flag.key])" :disabled="!model.writable() || !!state.gallery" @change="editor.field(flag.key,($event.target as HTMLSelectElement).value)"><option v-if="![0,1].includes(Number(editor.draft[flag.key]))" :value="String(editor.draft[flag.key])">历史值 {{ editor.draft[flag.key] }}（原样可保留）</option><option value="1">开启</option><option value="0">关闭</option></select></label>
   <div class="dialog-preview"><span>预览</span><span v-if="Number(editor.draft.style_type)!==2" class="word-preview" :style="wordStyle(editor.preview)">{{ editor.draft.label_name || '标签' }}</span><img v-else-if="editor.preview.icon" :key="editor.imageKey" :src="editor.preview.icon" alt="图片标签效果预览" @error="editor.imageError" /><span v-else>图片暂无可用预览</span></div>
   <template #footer><el-button :disabled="state.busy || !!state.gallery" @click="editor.cancel">取消</el-button><el-button type="primary" :disabled="!model.writable() || !!state.gallery" @click="editor.submit">保存标签</el-button></template>
  </el-dialog>
  <el-dialog v-for="editor in categoryEditors" :key="editor.key" class="product-label-author-dialog" top="16px" :model-value="true" :title="state.categoryEditor?.row?'编辑标签分组':'添加标签分组'" width="min(500px, calc(100vw - 24px))" :show-close="false" :close-on-click-modal="false" :close-on-press-escape="false"><el-alert v-if="state.error" :title="state.error" type="error" :closable="false" /><label class="field">分组名称<input aria-label="编辑标签分组名称" :value="editor.draft.name" @input="editor.field('name',($event.target as HTMLInputElement).value)" @keyup.enter="editor.submit" /></label><p class="sub">{{ editor.count }}/30 个字符；未修改的历史名称可原样保留。</p><label class="field">分组排序<input aria-label="编辑标签分组排序" :value="String(editor.draft.sort)" inputmode="numeric" @input="editor.field('sort',($event.target as HTMLInputElement).value)" @keyup.enter="editor.submit" /></label><template #footer><el-button :disabled="state.busy" @click="editor.cancel">取消</el-button><el-button type="primary" :disabled="!model.writable()" @click="editor.submit">保存分组</el-button></template></el-dialog>
  <el-dialog v-for="gallery in galleries" :key="gallery.key" class="product-label-author-dialog product-label-gallery" top="16px" :model-value="true" title="选择商品标签图标" width="min(760px, calc(100vw - 24px))" :show-close="false" :close-on-click-modal="false" :close-on-press-escape="false"><el-alert v-if="gallery.error" :title="gallery.error" type="error" :closable="false" /><div class="gallery-filters"><label class="field">图片分类<select aria-label="图库分类" :value="gallery.pid" @change="gallery.category(($event.target as HTMLSelectElement).value)"><option value="0">根目录</option><option v-for="category in gallery.categories" :key="category.id" :value="category.id">{{ category.name }}</option></select></label><label class="field">图片名称<input aria-label="图库名称" :value="gallery.name" @input="gallery.nameInput(($event.target as HTMLInputElement).value)" @keyup.enter="gallery.search" /></label><el-button :disabled="gallery.loading" @click="gallery.search">查询图片</el-button><el-button :disabled="gallery.loading" @click="gallery.refresh">刷新图片</el-button></div><p v-if="gallery.loading" role="status">正在读取图库…</p><div v-else class="image-grid"><div v-for="option in gallery.items" :key="option.key" class="image-option"><img v-if="option.row.preview" :src="option.row.preview" :alt="option.row.real_name" @error="option.error" /><span v-else>图片预览不可用</span><span>{{ option.row.real_name }}</span><el-button :disabled="!option.row.preview" @click="option.choose">选择此图</el-button></div></div><nav class="pager actions"><span>共 {{ gallery.count }} 项，第 {{ gallery.page }}/{{ gallery.pages }} 页</span><el-button :disabled="gallery.loading || gallery.page<=1" @click="gallery.previous">图库上一页</el-button><el-button :disabled="gallery.loading || gallery.page>=gallery.pages" @click="gallery.next">图库下一页</el-button></nav><template #footer><el-button @click="gallery.close">关闭图库</el-button></template></el-dialog>
  <el-dialog v-for="confirmation in confirmations" :key="confirmation.key" class="product-label-author-dialog" top="16px" :model-value="true" title="确认商品标签操作" width="min(560px, calc(100vw - 24px))" :show-close="false" :close-on-click-modal="false" :close-on-press-escape="false"><p>{{ operationLabels[confirmation.operation] }}<span v-if="confirmation.id"> #{{ confirmation.id }}</span></p><p v-if="confirmation.operation==='label-create'||confirmation.operation==='label-update'">{{ confirmation.payload.label_name }} · 分组 {{ confirmation.payload.label_cate }}；十项原始值完整保存，预览链接不会回写。</p><p v-else-if="confirmation.operation==='category-create'||confirmation.operation==='category-update'">{{ confirmation.payload.name }} · 排序 {{ confirmation.payload.sort }}</p><p v-else-if="confirmation.operation==='label-batch-delete'">选中ID：{{ confirmation.payload.ids }}。默认标签ID1至5会保留，其余仍有商品或历史辅助引用时整批拒绝。</p><p v-else-if="confirmation.operation==='category-delete'">分组1保留；仍有任何标签引用时拒绝删除，不迁移或丢弃标签。</p><p v-else-if="confirmation.operation==='label-delete'">物理删除此标签；默认标签及有商品或历史辅助引用的标签会保留。不会删除商品。</p><p v-else>仅修改当前标签的{{ confirmation.operation==='label-status'?'启用':'商城展示' }}状态，不改写其它字段。</p><template #footer><el-button :disabled="state.busy" @click="confirmation.cancel">取消操作</el-button><el-button type="primary" :disabled="state.busy" @click="confirmation.confirm">确认提交</el-button></template></el-dialog>
 </main>
</template>
<script setup lang="ts">
import { computed, reactive, watch, onMounted, onBeforeUnmount } from 'vue';
import { useRoute } from 'vue-router';
import { useAuthStore } from '@/stores/auth';
import { getAdminSession, getToken } from '@/utils/auth';
import { apiProductLabelAuthorCatalog, apiProductLabelAuthorCommit, apiProductLabelAuthorReceipt, apiProductLabelAuthorResolve, apiProductLabelAuthorAttachmentCategories, apiProductLabelAuthorAttachmentOptions } from '@/api/productLabelAuthor';
import { productLabelAuthorState } from '@/utils/productLabelAuthorState';
import type { ProductLabelAction, ProductLabelOperation } from '../../../../common/productLabelAuthor';
const props = withDefaults(defineProps<{ active?: boolean }>(), { active: true });
const emit = defineEmits<{ changed: [] }>();
const auth = useAuthStore(), route = useRoute();
let alive = false, generation = 0, syncing = false, queued = false;
const allowed = (values: string[]) => auth.uniqueAuth.some(p => p === '*' || p === 'label.*' || values.includes(p));
const canView = computed(() => props.active && !!auth.token && auth.token === getToken() && !!auth.userInfo && (auth.userInfo.level === 0 || allowed(['label.view', 'label.manage'])));
const canManage = computed(() => canView.value && (auth.userInfo?.level === 0 || allowed(['label.manage'])));
const prefix = (actor: number) => `cinashop_product_label_pending_v1_${actor}_`;
function keys(actor: number) { const result: string[] = []; for (let i = 0; i < localStorage.length; i++) { const key = localStorage.key(i); if (key?.startsWith(prefix(actor))) result.push(key); } return result.sort(); }
const model = productLabelAuthorState({ identity: () => `${generation}:${auth.token}:${auth.userInfo?.id}`, actor: () => auth.userInfo?.id ?? 0,
 view: () => canView.value, manage: () => canManage.value, read: apiProductLabelAuthorCatalog, write: apiProductLabelAuthorCommit, receipt: apiProductLabelAuthorReceipt, resolve: apiProductLabelAuthorResolve, categories: apiProductLabelAuthorAttachmentCategories, options: apiProductLabelAuthorAttachmentOptions, changed: () => emit('changed'),
 readPending: actor => { const key = keys(actor)[0]; if (!key) return null; const raw = localStorage.getItem(key); if (!raw || raw.length > 512 * 1024) throw Error('原商品标签操作记录异常，请保留核对'); const a = JSON.parse(raw); if (key !== prefix(actor) + a?.operation_id) throw Error('原商品标签操作标识不一致'); return a; },
 persist: (actor: number, a: ProductLabelAction | null, expected?: ProductLabelAction) => {
  const value = a ?? expected; if (!value) throw Error('缺少原商品标签操作'); const key = prefix(actor) + value.operation_id, raw = localStorage.getItem(key);
  if (a) { const text = JSON.stringify(a); if (text.length > 512 * 1024 || raw && raw !== text) throw Error('本账号已有其它未确认商品标签操作'); localStorage.setItem(key, text); }
  else { if (raw && raw !== JSON.stringify(expected)) throw Error('原商品标签操作记录已变化，无法清除'); localStorage.removeItem(key); }
 },
}, v => reactive(v) as typeof v);
const state = model.state, screens = computed(() => [model.screen()]), editors = computed(() => model.editorControls()), confirmations = computed(() => model.confirmationControls()), galleries = computed(() => model.galleryControls());
const visible = computed(() => model.visible()), pageCount = computed(() => model.pageCount());
const categoryEditors=computed(()=>model.categoryEditorControls()),visibleGroups=computed(()=>model.visibleGroups()),groupPageCount=computed(()=>model.groupPageCount()),groups=computed(()=>visibleGroups.value.slice((state.filters.groupPage-1)*15,state.filters.groupPage*15).map(model.groupControls));
const rows = computed(() => visible.value.slice((state.filters.page - 1) * 15, state.filters.page * 15).map(model.rowControls));
const colourFields = [{ key: 'color', label: '字体颜色' }, { key: 'bg_color', label: '背景颜色' }, { key: 'border_color', label: '边框颜色' }] as const;
function wordStyle(value: { color: string; bg_color: string; border_color: string }) { return { color: value.color || '#666', backgroundColor: value.bg_color || '#f5f5f5', border: value.border_color ? `1px solid ${value.border_color}` : 'none' }; }
const flagFields=[{key:'status',label:'是否开启'},{key:'is_show',label:'移动端展示'}] as const;
const operationLabels:Record<ProductLabelOperation,string>={'label-create':'新增商品标签','label-update':'保存商品标签','label-status':'修改启用状态','label-show':'修改商城展示','label-delete':'删除商品标签','label-batch-delete':'批量删除商品标签','category-create':'新增标签分组','category-update':'保存标签分组','category-delete':'删除标签分组'};
function flagLabel(value:number){return value===1?'开启':value===0?'关闭':`历史状态 ${value}`;}
function groupName(id:number){return state.snapshot?.groups.find(row=>row.id===id)?.name||(id===0?'未分组历史标签':`历史分组 #${id}`);}
function addedTime(value: number) { if (!value) return '—'; return new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }).format(new Date(value * 1000)); }
function schedule() {
 if (!alive || syncing) return; generation++; model.dispose(); if (queued) return; queued = true;
 queueMicrotask(() => { queued = false; if (alive && props.active) void model.activate(); });
}
function syncStored(event?: Event) {
 if (syncing || event instanceof StorageEvent && event.key !== null && !['admin_token', 'admin_session'].includes(event.key) && !event.key.startsWith('cinashop_product_label_pending_v1_')) return;
 syncing = true; generation++; model.dispose(); const session = getAdminSession();
